// ❌ OLD: Web applications without a Service Worker cannot intercept
// failed requests, rendering the application completely broken when offline.
async function loadDashboard() {
  const res = await fetch('/api/dashboard');
  const data = await res.json();
  render(data);
}

const CACHE_NAME = 'app-v1';
const ASSETS = ['/', '/index.html', '/styles.css', '/bundle.js'];

// ✅ NEW: Pre-cache static shell during installation
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => cache.addAll(ASSETS))
  );
  self.skipWaiting();
});

// ✅ NEW: Clean up old cache versions during activation
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k)))
    )
  );
  self.clients.claim();
});

// ✅ NEW: Intercept all outgoing fetch requests
self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request).then((cachedResponse) => {
      return cachedResponse || fetch(event.request);
    })
  );
});
